//! One compilation policy, with developer-only pass isolation for diagnosis.

/// Identity of the normal compilation strategy. Compiler upgrades may change
/// generated bytes; deployment must always bind the actual checked artifact.
pub const COMPILATION_POLICY: &str = "cellscript-unified-v1";

/// Optional transformations that can be isolated while diagnosing the compiler.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum OptimizationPass {
    ConstantFolding,
    Inlining,
    DeadCode,
    ExactCellEquality,
    SourceByteEquality,
    ExactReadHotCache,
    StackReloads,
    BranchFusion,
}

/// Internal diagnostic controls, deliberately absent from CLI and wire formats.
/// Disabling a pass is an experiment, not an alternative release strategy.
#[doc(hidden)]
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Hash)]
pub struct CompilerDiagnostics {
    disabled: u8,
}

impl CompilerDiagnostics {
    pub const fn without_optimizations() -> Self {
        Self { disabled: u8::MAX }
    }

    pub const fn without(mut self, pass: OptimizationPass) -> Self {
        self.disabled |= 1 << pass as u8;
        self
    }

    pub const fn enabled(self, pass: OptimizationPass) -> bool {
        self.disabled & (1 << pass as u8) == 0
    }

    pub const fn is_standard(self) -> bool {
        self.disabled == 0
    }

    pub(crate) const fn cache_bits(self) -> u8 {
        self.disabled
    }
}

impl std::fmt::Display for CompilerDiagnostics {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        if self.is_standard() {
            formatter.write_str("standard")
        } else {
            write!(formatter, "diagnostic:{:02x}", self.disabled)
        }
    }
}
